const body = $input.first().json.body ?? $input.first().json;

if (!body.telefono) throw new Error('T1a: falta telefono');
if (!body.user_text) throw new Error('T1a: falta user_text');
if (!body.session) throw new Error('T1a: falta session');
if (!body.session.fecha_renta) throw new Error('T1a: falta session.fecha_renta');
if (!body.session.hora_inicio) throw new Error('T1a: falta session.hora_inicio');
if (!body.session.hora_fin) throw new Error('T1a: falta session.hora_fin');

return [{
  json: {
    telefono: String(body.telefono).replace(/\D/g, ''),
    user_text: String(body.user_text).trim(),
    session: {
      ...body.session,
      telefono: String(body.telefono).replace(/\D/g, ''),
    },
    purpose: 'disponibilidad',
    tipo: 'BR',
    solo_disponibles: true,
    limit: 15,
  }
}];

// === BR Rewrite (canónico + merge prep T1a) ===
const __prep = $input.first().json;
const text = String(__prep.user_text || '').trim();
if (!text) throw new Error('BR Rewrite: falta user_text');

const raw = text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const synonyms = {
  chiquito: 'chico', chiquita: 'chico', pequeno: 'chico',
  grande: 'grande', tobogan: 'tobogan', 'hombre arana': 'spiderman',
};
let normalized = raw;
for (const [from, to] of Object.entries(synonyms)) {
  normalized = normalized.replace(new RegExp(from.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'), to);
}
const stop = new Set(['con','de','el','la','los','las','un','una','para','brincolin','brincolines']);
const tokens = normalized.split(/[^a-z0-9]+/).map(t => synonyms[t] || t)
  .filter(t => t.length >= 2 && !stop.has(t)).slice(0, 6);
const unique = [...new Set(tokens)];

return [{
  json: {
    ...__prep,
    user_text: text,
    search_tokens: unique,
    query_crm: unique.join(' '),
    search: unique.join(' '),
    tipo: 'BR',
    alt_queries: unique.length > 1 ? [unique[0]] : [],
    needs_human: unique.length === 0,
    reason: unique.length ? null : 'No se pudo extraer tokens de búsqueda',
  },
}];

/**
 * Nodo Code n8n — nombre FIJO: "Session To CRM Query"
 *
 * Único convertidor Session → payloads CRM.
 * Shapes SEPARADOS a propósito (no mezclar GET y POST):
 *
 *   disponibilidad_query / disponibilidad_qs
 *     → SOLO para GET /v1/bot/disponibilidad/
 *     → Nunca incluye productos, dirección ni cliente
 *
 *   cotizacion_body
 *     → SOLO para POST /v1/bot/cotizacion/
 *     → horario (fecha_renta) + productos + manteles_regalo?
 *
 *   renta_crear_body
 *     → SOLO para POST /v1/bot/renta/crear/
 *     → body completo (cliente, dirección, productos, horario, anticipo…)
 *
 * Input:
 *   $json.purpose = "disponibilidad" | "cotizacion" | "renta_crear"
 *   (default: "disponibilidad")
 *   + session en $json / $json.session / nodo "Session"
 *   + extras: tipo, search|query_crm, solo_disponibles, limit, accion…
 *
 * Si falta un campo requerido para el purpose → THROW ruidoso
 * (no dejar que el CRM conteste 400 genérico dos nodos después).
 */

const SESSION_NODE = 'Session';
const PURPOSE = String(($input.first().json || {}).purpose || 'disponibilidad').toLowerCase();

function loadSession() {
  const direct = $input.first().json || {};
  if (direct.session && typeof direct.session === 'object') {
    return { ...direct.session };
  }
  try {
    return { ...$(SESSION_NODE).first().json };
  } catch (_) {
    return { ...direct };
  }
}

function requireFields(obj, fields, ctx) {
  const missing = fields.filter((f) => {
    const v = obj[f];
    if (v === undefined || v === null) return true;
    if (typeof v === 'string' && !v.trim()) return true;
    if (Array.isArray(v) && v.length === 0) return true;
    return false;
  });
  if (missing.length) {
    throw new Error(
      `session_to_crm_query: falta ${missing.join(', ')} en session ` +
      `(purpose=${ctx}). No llames al CRM hasta completar el flujo conversacional.`
    );
  }
}

const extras = $input.first().json || {};
const session = loadSession();

// Horario: canónico en session es fecha_renta (no fecha)
const fecha_renta = session.fecha_renta || extras.fecha_renta;
const hora_inicio = session.hora_inicio || extras.hora_inicio;
const hora_fin = session.hora_fin || extras.hora_fin;

const horario = {
  fecha_renta: fecha_renta ? String(fecha_renta) : '',
  hora_inicio: hora_inicio ? String(hora_inicio) : '',
  hora_fin: hora_fin ? String(hora_fin) : '',
};

// ─── GET /bot/disponibilidad/ ─────────────────────────────────────────
requireFields(horario, ['fecha_renta', 'hora_inicio', 'hora_fin'], PURPOSE === 'disponibilidad' ? 'disponibilidad' : `${PURPOSE}/horario`);

const tipo = extras.tipo || session.tipo_busqueda || '';
const search = extras.search ?? extras.query_crm ?? session.query_crm ?? '';
const solo_disponibles = extras.solo_disponibles ?? true;
const limit = extras.limit ?? 15;

const disponibilidad_query = {
  fecha: horario.fecha_renta, // RENAME session.fecha_renta → ?fecha=
  hora_inicio: horario.hora_inicio,
  hora_fin: horario.hora_fin,
  solo_disponibles: solo_disponibles ? 'true' : 'false',
  limit: String(limit),
};
if (tipo) disponibilidad_query.tipo = String(tipo);
if (search) disponibilidad_query.search = String(search);

const disponibilidad_qs = Object.entries(disponibilidad_query)
  .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
  .join('&');

// ─── POST /bot/cotizacion/ ────────────────────────────────────────────
let cotizacion_body = null;
if (PURPOSE === 'cotizacion' || PURPOSE === 'renta_crear') {
  const productos = session.productos || extras.productos;
  requireFields({ ...horario, productos }, ['fecha_renta', 'hora_inicio', 'hora_fin', 'productos'], 'cotizacion');
  cotizacion_body = {
    fecha_renta: horario.fecha_renta,
    hora_inicio: horario.hora_inicio,
    hora_fin: horario.hora_fin,
    productos,
    manteles_regalo: session.manteles_regalo || extras.manteles_regalo || [],
  };
}

// ─── POST /bot/renta/crear/ ───────────────────────────────────────────
let renta_crear_body = null;
if (PURPOSE === 'renta_crear') {
  const telefono = session.telefono || extras.telefono;
  const productos = session.productos || extras.productos;
  requireFields(
    { ...horario, telefono, productos },
    ['fecha_renta', 'hora_inicio', 'hora_fin', 'telefono', 'productos'],
    'renta_crear'
  );

  renta_crear_body = {
    telefono: String(telefono).replace(/\D/g, ''),
    cliente_nombre: session.cliente_nombre || session.nombre || extras.nombre || '',
    calle_y_numero: session.direccion || session.calle_y_numero || extras.direccion || '',
    colonia: session.colonia || extras.colonia || '',
    ciudad_o_municipio: session.ciudad || session.ciudad_o_municipio || extras.ciudad || '',
    mismo_domicilio: session.mismo_domicilio ?? extras.mismo_domicilio ?? true,
    fecha_renta: horario.fecha_renta,
    hora_inicio: horario.hora_inicio,
    hora_fin: horario.hora_fin,
    productos,
    manteles_regalo: session.manteles_regalo || extras.manteles_regalo || [],
    anticipo: session.anticipo ?? extras.anticipo ?? 0,
    notas: session.notas || extras.notas || '',
    accion: 'crear',
  };
}

// Salida: shapes hermanos, no un mega-objeto ambiguo
const out = {
  purpose: PURPOSE,
  // GET only
  disponibilidad_query,
  disponibilidad_qs,
  // POST cotizacion only (null si purpose=disponibilidad)
  cotizacion_body,
  // POST renta/crear only (null si purpose≠renta_crear)
  renta_crear_body,
  _map: {
    'session.fecha_renta → GET': 'disponibilidad_query.fecha',
    'session.fecha_renta → POST': 'cotizacion_body.fecha_renta | renta_crear_body.fecha_renta',
  },
};

if (PURPOSE === 'disponibilidad') {
  // No exponer bodies POST parcialmente construidos por accidente
  out.cotizacion_body = null;
  out.renta_crear_body = null;
}
if (PURPOSE === 'cotizacion') {
  out.renta_crear_body = null;
}

return [{ json: out }];

/**
 * Nodo Code n8n — nombre FIJO: "BR Rerank"
 *
 * Rutas de salida:
 *  A) CONTRATO ROTO  → throw (técnico)
 *     - falta nodo Rewrite/HTTP
 *     - HTTP no trae array "resultados" (undefined/null/no-array)
 *     - id fuera del set CRM
 *  B) NEGOCIO SIN MATCH → return conversacional (NO throw)
 *     - resultados: []  (array vacío válido)
 *
 * Tokens:
 *  - search_tokens_rewrite ← $('BR Rewrite').search_tokens  (scoring)
 *  - search_tokens_crm     ← $('BR HTTP Disponibilidad').search_tokens (audit)
 */

const REWRITE = 'BR Rewrite';
const HTTP = 'BR HTTP Disponibilidad';

function nodeJson(name) {
  try {
    return $(name).first().json;
  } catch (err) {
    throw new Error(
      `BR Rerank: CONTRATO — no encuentro el nodo "${name}". ` +
      `Renómbralo exactamente así.`
    );
  }
}

const rewrite = nodeJson(REWRITE);
const http = nodeJson(HTTP);

const userText = rewrite.user_text || '';
const search_tokens_rewrite = Array.isArray(rewrite.search_tokens)
  ? rewrite.search_tokens.map((t) => String(t).toLowerCase())
  : [];
const search_tokens_crm = Array.isArray(http.search_tokens)
  ? http.search_tokens.map((t) => String(t).toLowerCase())
  : [];

// --- Fix 1: forma del campo vs vacío de negocio ---
// null  = contrato roto (falta key o no es array) → THROW
// []    = 0 matches reales → mensaje conversacional
const resultadosRaw = Object.prototype.hasOwnProperty.call(http, 'resultados')
  ? http.resultados
  : (Object.prototype.hasOwnProperty.call(http, 'candidatos') ? http.candidatos : undefined);

if (!Array.isArray(resultadosRaw)) {
  throw new Error(
    `BR Rerank: CONTRATO — "${HTTP}" debe exponer array "resultados". ` +
    `Recibido typeof=${typeof resultadosRaw}; keys=${Object.keys(http || {}).join(',') || '(vacío)'}`
  );
}

const resultados = resultadosRaw;

// Scoring usa SOLO tokens del rewrite (sinónimos). CRM tokens son audit.
const tokens = search_tokens_rewrite;

if (resultados.length === 0) {
  const alts = Array.isArray(rewrite.alt_queries) ? rewrite.alt_queries : [];
  const hint = alts.length ? `\nPrueba: ${alts.join(', ')}` : '\nPrueba otra palabra (tema, tamaño)';
  return [{
    json: {
      preferred_order_ids: [],
      top_n: 5,
      needs_human: false, // negocio: reintentar búsqueda, no handoff técnico
      reason: 'no_matches',
      confidence: 0,
      top: [],
      menu_whatsapp:
        `No encontré brincolines con "${userText}".${hint}\n` +
        '0. Buscar de nuevo\n9. Hablar con un asesor',
      search_tokens_rewrite,
      search_tokens_crm,
      _debug: {
        query_crm: rewrite.query_crm || null,
        http_count: http.count ?? 0,
        exit: 'business_empty',
      },
    },
  }];
}

function score(nombre) {
  const n = String(nombre || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
  let s = 0;
  for (const t of tokens) {
    if (n.includes(t)) s += 2;
  }
  return s;
}

const crmIds = new Set(resultados.map((c) => c.id));

const ranked = [...resultados]
  .filter((c) => c && c.id != null && c.disponible !== false)
  .map((c) => ({ ...c, _score: score(c.nombre) }))
  .sort((a, b) => b._score - a._score || String(a.nombre).localeCompare(String(b.nombre)));

const topN = 5;
const top = ranked.slice(0, topN).map(({ _score, ...rest }) => rest);
const ids = top.map((c) => c.id);

for (const id of ids) {
  if (!crmIds.has(id)) {
    throw new Error(`BR Rerank: CONTRATO — id ${id} no está en resultados CRM`);
  }
}

const lines = top.map((c, i) => {
  const libres = c.unidades_libres ?? '?';
  return `${i + 1}. ${c.nombre} — $${c.precio} (${libres} libres)`;
});

const menu = [
  'Encontré estas opciones:',
  ...lines,
  '',
  '0. Buscar de nuevo',
  '9. Hablar con un asesor',
].join('\n');

return [{
  json: {
    preferred_order_ids: ids,
    top_n: topN,
    needs_human: false,
    reason: null,
    confidence: tokens.length ? Math.min(1, (ranked[0]?._score || 0) / (tokens.length * 2)) : 0.5,
    top,
    menu_whatsapp: menu,
    search_tokens_rewrite,
    search_tokens_crm,
    _debug: {
      user_text: userText,
      http_count: http.count ?? resultados.length,
      exit: 'ok',
    },
  },
}];

const rerank = $input.first().json;
const prep = $('T1a Preparar Input').item.json;

const staticData = $getWorkflowStaticData('global');
if (!staticData.br_searches) staticData.br_searches = {};

const now = Date.now();
const TTL_MS = 15 * 60 * 1000;
for (const [id, entry] of Object.entries(staticData.br_searches)) {
  if (now - entry.created_at > TTL_MS) delete staticData.br_searches[id];
}

const hasTop = Array.isArray(rerank.top) && rerank.top.length > 0;
const searchId = hasTop ? `br_${prep.telefono}_${now}` : null;

if (hasTop) {
  staticData.br_searches[searchId] = {
    created_at: now,
    telefono: prep.telefono,
    session: prep.session,
    top: rerank.top,
    query_crm: $('BR Rewrite').item.json.query_crm || null,
  };
}

return [{
  json: {
    ok: hasTop,
    search_id: searchId,
    expires_in_sec: hasTop ? 900 : null,
    menu_whatsapp: rerank.menu_whatsapp,
    needs_human: rerank.needs_human,
    reason: rerank.reason,
    top: rerank.top || [],
    preferred_order_ids: rerank.preferred_order_ids || [],
    search_tokens_rewrite: rerank.search_tokens_rewrite,
    search_tokens_crm: rerank.search_tokens_crm,
    _debug: rerank._debug || null,
  }
}];

const body = $input.first().json.body ?? $input.first().json;

if (!body.search_id) throw new Error('T1b: falta search_id');
if (body.choice === undefined || body.choice === null || body.choice === '') {
  throw new Error('T1b: falta choice (número de opción, 0 = buscar de nuevo)');
}

const choice = Number(body.choice);
const staticData = $getWorkflowStaticData('global');
const entry = staticData.br_searches && staticData.br_searches[body.search_id];

if (!entry) {
  throw new Error(
    `T1b: search_id "${body.search_id}" no encontrado o expirado (TTL 15 min). Vuelve a correr T1a.`
  );
}

// choice 0 = buscar de nuevo (turno conversacional, no llama motor)
if (choice === 0) {
  return [{
    json: {
      ok: false,
      reason: 'search_again',
      needs_human: false,
      mensaje_whatsapp: 'Ok, escribe de nuevo qué brincolín buscas (tema, tamaño…).',
      skip_motor: true,
      telefono: entry.telefono,
      session: entry.session,
    }
  }];
}

const idx = choice - 1;
const item = entry.top[idx];
if (!item) {
  throw new Error(
    `T1b: choice=${choice} fuera de rango. Opciones válidas: 1-${entry.top.length} (o 0 para buscar de nuevo)`
  );
}

const purpose = body.purpose === 'renta_crear' ? 'renta_crear' : 'cotizacion';

return [{
  json: {
    skip_motor: false,
    telefono: entry.telefono,
    session: {
      ...entry.session,
      telefono: entry.telefono,
      productos: [{ id: item.id, cantidad: 1 }],
    },
    productos: [{ id: item.id, cantidad: 1 }],
    producto_elegido: item,
    purpose,
  }
}];

/**
 * Nodo Code n8n — nombre FIJO: "Session To CRM Query"
 *
 * Único convertidor Session → payloads CRM.
 * Shapes SEPARADOS a propósito (no mezclar GET y POST):
 *
 *   disponibilidad_query / disponibilidad_qs
 *     → SOLO para GET /v1/bot/disponibilidad/
 *     → Nunca incluye productos, dirección ni cliente
 *
 *   cotizacion_body
 *     → SOLO para POST /v1/bot/cotizacion/
 *     → horario (fecha_renta) + productos + manteles_regalo?
 *
 *   renta_crear_body
 *     → SOLO para POST /v1/bot/renta/crear/
 *     → body completo (cliente, dirección, productos, horario, anticipo…)
 *
 * Input:
 *   $json.purpose = "disponibilidad" | "cotizacion" | "renta_crear"
 *   (default: "disponibilidad")
 *   + session en $json / $json.session / nodo "Session"
 *   + extras: tipo, search|query_crm, solo_disponibles, limit, accion…
 *
 * Si falta un campo requerido para el purpose → THROW ruidoso
 * (no dejar que el CRM conteste 400 genérico dos nodos después).
 */

const SESSION_NODE = 'Session';
const PURPOSE = String(($input.first().json || {}).purpose || 'disponibilidad').toLowerCase();

function loadSession() {
  const direct = $input.first().json || {};
  if (direct.session && typeof direct.session === 'object') {
    return { ...direct.session };
  }
  try {
    return { ...$(SESSION_NODE).first().json };
  } catch (_) {
    return { ...direct };
  }
}

function requireFields(obj, fields, ctx) {
  const missing = fields.filter((f) => {
    const v = obj[f];
    if (v === undefined || v === null) return true;
    if (typeof v === 'string' && !v.trim()) return true;
    if (Array.isArray(v) && v.length === 0) return true;
    return false;
  });
  if (missing.length) {
    throw new Error(
      `session_to_crm_query: falta ${missing.join(', ')} en session ` +
      `(purpose=${ctx}). No llames al CRM hasta completar el flujo conversacional.`
    );
  }
}

const extras = $input.first().json || {};
const session = loadSession();

// Horario: canónico en session es fecha_renta (no fecha)
const fecha_renta = session.fecha_renta || extras.fecha_renta;
const hora_inicio = session.hora_inicio || extras.hora_inicio;
const hora_fin = session.hora_fin || extras.hora_fin;

const horario = {
  fecha_renta: fecha_renta ? String(fecha_renta) : '',
  hora_inicio: hora_inicio ? String(hora_inicio) : '',
  hora_fin: hora_fin ? String(hora_fin) : '',
};

// ─── GET /bot/disponibilidad/ ─────────────────────────────────────────
requireFields(horario, ['fecha_renta', 'hora_inicio', 'hora_fin'], PURPOSE === 'disponibilidad' ? 'disponibilidad' : `${PURPOSE}/horario`);

const tipo = extras.tipo || session.tipo_busqueda || '';
const search = extras.search ?? extras.query_crm ?? session.query_crm ?? '';
const solo_disponibles = extras.solo_disponibles ?? true;
const limit = extras.limit ?? 15;

const disponibilidad_query = {
  fecha: horario.fecha_renta, // RENAME session.fecha_renta → ?fecha=
  hora_inicio: horario.hora_inicio,
  hora_fin: horario.hora_fin,
  solo_disponibles: solo_disponibles ? 'true' : 'false',
  limit: String(limit),
};
if (tipo) disponibilidad_query.tipo = String(tipo);
if (search) disponibilidad_query.search = String(search);

const disponibilidad_qs = Object.entries(disponibilidad_query)
  .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
  .join('&');

// ─── POST /bot/cotizacion/ ────────────────────────────────────────────
let cotizacion_body = null;
if (PURPOSE === 'cotizacion' || PURPOSE === 'renta_crear') {
  const productos = session.productos || extras.productos;
  requireFields({ ...horario, productos }, ['fecha_renta', 'hora_inicio', 'hora_fin', 'productos'], 'cotizacion');
  cotizacion_body = {
    fecha_renta: horario.fecha_renta,
    hora_inicio: horario.hora_inicio,
    hora_fin: horario.hora_fin,
    productos,
    manteles_regalo: session.manteles_regalo || extras.manteles_regalo || [],
  };
}

// ─── POST /bot/renta/crear/ ───────────────────────────────────────────
let renta_crear_body = null;
if (PURPOSE === 'renta_crear') {
  const telefono = session.telefono || extras.telefono;
  const productos = session.productos || extras.productos;
  requireFields(
    { ...horario, telefono, productos },
    ['fecha_renta', 'hora_inicio', 'hora_fin', 'telefono', 'productos'],
    'renta_crear'
  );

  renta_crear_body = {
    telefono: String(telefono).replace(/\D/g, ''),
    cliente_nombre: session.cliente_nombre || session.nombre || extras.nombre || '',
    calle_y_numero: session.direccion || session.calle_y_numero || extras.direccion || '',
    colonia: session.colonia || extras.colonia || '',
    ciudad_o_municipio: session.ciudad || session.ciudad_o_municipio || extras.ciudad || '',
    mismo_domicilio: session.mismo_domicilio ?? extras.mismo_domicilio ?? true,
    fecha_renta: horario.fecha_renta,
    hora_inicio: horario.hora_inicio,
    hora_fin: horario.hora_fin,
    productos,
    manteles_regalo: session.manteles_regalo || extras.manteles_regalo || [],
    anticipo: session.anticipo ?? extras.anticipo ?? 0,
    notas: session.notas || extras.notas || '',
    accion: 'crear',
  };
}

// Salida: shapes hermanos, no un mega-objeto ambiguo
const out = {
  purpose: PURPOSE,
  // GET only
  disponibilidad_query,
  disponibilidad_qs,
  // POST cotizacion only (null si purpose=disponibilidad)
  cotizacion_body,
  // POST renta/crear only (null si purpose≠renta_crear)
  renta_crear_body,
  _map: {
    'session.fecha_renta → GET': 'disponibilidad_query.fecha',
    'session.fecha_renta → POST': 'cotizacion_body.fecha_renta | renta_crear_body.fecha_renta',
  },
};

if (PURPOSE === 'disponibilidad') {
  // No exponer bodies POST parcialmente construidos por accidente
  out.cotizacion_body = null;
  out.renta_crear_body = null;
}
if (PURPOSE === 'cotizacion') {
  out.renta_crear_body = null;
}

return [{ json: out }];

const s = $input.first().json;

if (s.skip_motor) {
  return [{ json: s }];
}

const mapped = $('Session To CRM Query (T1b)').item.json;
const purpose = mapped.purpose;
let payload;

if (purpose === 'renta_crear') {
  payload = mapped.renta_crear_body;
} else {
  payload = mapped.cotizacion_body;
}

if (!payload) {
  throw new Error('Armar Payload Motor: body null para purpose=' + purpose);
}

// Motor trotacrm-crear-plan espera top-level accion + telefono + horario + productos
const motorBody = {
  ...payload,
  accion: purpose === 'renta_crear' ? 'crear' : 'cotizar',
  telefono: s.telefono || payload.telefono,
  nombre: payload.cliente_nombre || s.session?.cliente_nombre || '',
  direccion: payload.calle_y_numero || s.session?.direccion || '',
  colonia: payload.colonia || s.session?.colonia || '',
  ciudad: payload.ciudad_o_municipio || s.session?.ciudad || '',
};

return [{
  json: {
    skip_motor: false,
    purpose,
    motor_body: motorBody,
    producto_elegido: s.producto_elegido,
  }
}];

const prev = $('Armar Payload Motor').item.json;

if (prev.skip_motor) {
  return [{
    json: {
      ok: false,
      reason: prev.reason,
      needs_human: false,
      mensaje_whatsapp: prev.mensaje_whatsapp,
    }
  }];
}

const motor = $input.first().json;
return [{
  json: {
    ...motor,
    purpose: prev.purpose,
    producto_elegido: prev.producto_elegido,
  }
}];

const s = $input.first().json;
return [{
  json: {
    ok: false,
    reason: s.reason || 'search_again',
    needs_human: false,
    mensaje_whatsapp: s.mensaje_whatsapp,
  }
}];
